CREATE OR REPLACE PROCEDURE sp(para_ResID integer, para_ResName text, para_Address text, para_StuID integer, para_LName text, para_ResTypeID integer)
LANGUAGE plpgsql
AS $$
BEGIN
  IF para_ResID = 0 AND para_ResName = '%' THEN
    UPDATE "Restaurant" SET "ResName" = para_Address WHERE "ResName" LIKE para_ResName;
  ELSIF para_ResID = 4 AND para_ResName = 'PROCESSED' AND para_Address = 'IRRELEVANT' AND para_ResTypeID = 20 THEN
    UPDATE "Student" SET "Age" = "Age" + 1 WHERE "LName" = para_LName;
  ELSIF para_ResID = 5 AND para_ResName = 'PROCESSED' AND para_Address = 'IRRELEVANT' AND para_ResTypeID = 20 THEN
    UPDATE "Student" SET "LName" = 'BULK_PROCESSED' WHERE "StuID" >= para_StuID;
  ELSIF para_ResID = 12 AND para_ResTypeID = 0 THEN
    UPDATE "Restaurant_Type" SET "ResTypeID" = "ResTypeID" + 10;
  ELSIF para_ResID = 13 AND para_ResTypeID = 21 THEN
    UPDATE "Restaurant_Type" SET "ResTypeID" = "ResTypeID" + 10 WHERE "ResTypeID" = para_ResTypeID - 19;
  END IF;
END;
$$;

